"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";
import { StatusButton, type ActionStatus } from "./status-button";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * SETTINGS FORM: a settings page that saves the way people
 * expect it to
 *
 *   switch    toggles and choices save the moment they change:
 *             the thumb is thrown across, "Saving" opens beside
 *             the label, a check draws and fades. If the server
 *             says no, the thumb is thrown back with a shake
 *             and the reason opens under the field
 *   edit      text edits wait for you: a dot swells beside each
 *             changed label and one bar rises at the foot of
 *             the form, "2 unsaved changes", rolling as you go
 *   check     a field with an async check (is this address
 *             free?) asks a moment after you stop typing:
 *             "Checking", then "Available" or why not
 *   save      Save (or ⌘S) sends just what changed; the bar says
 *             Saving, then Saved, and folds away. Errors your
 *             server sends per field open under those fields
 *             and focus goes to the first
 *   reset     the edits blur back to what's saved
 *
 * Fields are plain objects; onSave gets only the changed values
 * and returns what was stored.
 * ───────────────────────────────────────────────────────── */

export type SettingsValue = string | boolean;
export type SettingsValues = Record<string, SettingsValue>;

type Base = { name: string; label: string; description?: string };

export type SettingsField =
  | (Base & { type: "toggle" })
  | (Base & { type: "choice"; options: { value: string; label: string }[] })
  | (Base & {
      type: "text" | "textarea";
      placeholder?: string;
      /** Shown inside the field before the value, e.g. "relay.app/". */
      prefix?: string;
      /** Textarea height in lines. */
      rows?: number;
      maxLength?: number;
      inputMode?: React.HTMLAttributes<HTMLInputElement>["inputMode"];
      autoComplete?: string;
      /** Return a message to refuse the value before it's sent. */
      validate?: (
        value: string,
        values: SettingsValues,
      ) => string | null | undefined | void;
      /** Asked a moment after typing stops: return null when the value is fine, or why it isn't. */
      check?: (
        value: string,
        options: { signal: AbortSignal },
      ) => Promise<string | null | undefined | void>;
      /** What a passed check says. */
      checkPassed?: string;
    });

export interface SettingsSection {
  title: string;
  description?: string;
  fields: SettingsField[];
}

/** Throw this from onSave to put messages under particular fields. */
export class SettingsFormError extends Error {
  fields: Record<string, string>;
  constructor(message: string, fields: Record<string, string> = {}) {
    super(message);
    this.name = "SettingsFormError";
    this.fields = fields;
  }
}

export interface SettingsFormProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "defaultValue" | "onChange"
> {
  sections: SettingsSection[];
  /** Saved values, controlled. */
  value?: SettingsValues;
  defaultValue?: SettingsValues;
  /** The saved values after every successful save. */
  onValueChange?: (values: SettingsValues) => void;
  /** Saves the changed values. Return what was stored (or nothing); throw to keep the edits and say why. */
  onSave: (
    patch: SettingsValues,
    values: SettingsValues,
  ) => Promise<SettingsValues | void> | SettingsValues | void;
  /** Toggles and choices save the moment they change. */
  autosave?: boolean;
  /** Ask before leaving the page with unsaved edits. */
  warnOnLeave?: boolean;
}

type Check = { state: "checking" | "ok" | "no"; message: string };
type TextField = Extract<SettingsField, { type: "text" | "textarea" }>;

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const THROW = "cubic-bezier(0.34,1.36,0.64,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const EMPTY: SettingsValues = {};
const SHAKE = [
  { transform: "none" },
  { transform: "translateX(-4px)" },
  { transform: "translateX(4px)" },
  { transform: "translateX(-2px)" },
  { transform: "none" },
];

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

const without = <T,>(o: Record<string, T>, keys: string[]) =>
  Object.fromEntries(
    Object.entries(o).filter(([k]) => !keys.includes(k)),
  ) as Record<string, T>;
const message = (e: unknown, fallback: string) =>
  e instanceof Error && e.message ? e.message : fallback;

function DrawnCheck({
  drawn,
  reduced,
  className = "size-3.5",
}: {
  drawn: boolean;
  reduced: boolean;
  className?: string;
}) {
  return (
    <svg
      viewBox="0 0 16 16"
      fill="none"
      aria-hidden="true"
      className={className}
    >
      <path
        d="M3.5 8.5 6.5 11.5 12.5 4.5"
        stroke="currentColor"
        strokeWidth="1.8"
        strokeLinecap="round"
        strokeLinejoin="round"
        pathLength={1}
        strokeDasharray={1}
        style={{
          strokeDashoffset: drawn ? 0 : 1,
          transition:
            drawn && !reduced
              ? `stroke-dashoffset 380ms ${EASE} 100ms`
              : "none",
        }}
      />
    </svg>
  );
}

function Spinner({ on }: { on: boolean }) {
  return (
    <span
      className={`size-3 rounded-full border-[1.5px] border-current border-t-transparent motion-reduce:animate-none ${on ? "animate-spin" : ""}`}
    />
  );
}

/** Text that changes by lifting the old line out through a blur and the new one in (sentences don't morph letter by letter). */
function Line({
  text,
  className = "",
  reduced,
}: {
  text: string;
  className?: string;
  reduced: boolean;
}) {
  const [shown, setShown] = React.useState(text);
  const [leaving, setLeaving] = React.useState<{ key: number; text: string }[]>(
    [],
  );
  const key = React.useRef(0);
  const ref = React.useRef<HTMLSpanElement>(null);
  if (text !== shown) {
    if (!reduced && shown)
      setLeaving((l) => [...l, { key: ++key.current, text: shown }]);
    setShown(text);
  }
  React.useLayoutEffect(() => {
    if (reduced || !ref.current || !leaving.length) return;
    ref.current.animate(
      [
        { opacity: 0, transform: "translateY(4px)", filter: "blur(3px)" },
        { opacity: 1, transform: "none", filter: "blur(0px)" },
      ],
      { duration: 320, delay: 60, easing: EASE, fill: "backwards" },
    );
  }, [shown]);
  return (
    <span className={`relative block ${className}`}>
      <span ref={ref} className="block">
        {shown}
      </span>
      {leaving.map((l) => (
        <LeavingLine
          key={l.key}
          text={l.text}
          onDone={() => setLeaving((all) => all.filter((x) => x.key !== l.key))}
        />
      ))}
    </span>
  );
}

function LeavingLine({ text, onDone }: { text: string; onDone: () => void }) {
  const ref = React.useRef<HTMLSpanElement>(null);
  React.useLayoutEffect(() => {
    const a = ref.current?.animate(
      [
        { opacity: 1, filter: "blur(0px)" },
        { opacity: 0, transform: "translateY(-4px)", filter: "blur(3px)" },
      ],
      { duration: 200, easing: EASE, fill: "forwards" },
    );
    if (a) a.onfinish = onDone;
    return () => a?.cancel();
  }, []);
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className="pointer-events-none absolute inset-x-0 top-0 block"
    >
      {text}
    </span>
  );
}

/** A block that opens and closes by height, keeping its last children while it closes. */
function Fold({
  open,
  reduced,
  children,
}: {
  open: boolean;
  reduced: boolean;
  children: React.ReactNode;
}) {
  const [kept, setKept] = React.useState(children);
  if (open && kept !== children) setKept(children);
  return (
    <div
      className="grid"
      inert={!open}
      aria-hidden={!open || undefined}
      style={{
        gridTemplateRows: open ? "1fr" : "0fr",
        opacity: open ? 1 : 0,
        transition: reduced
          ? "none"
          : `grid-template-rows 380ms ${EASE}, opacity 260ms ${EASE}`,
      }}
    >
      <div className="min-h-0 overflow-clip">{open ? children : kept}</div>
    </div>
  );
}

/** "Saving" → "Saved" beside a label that saved itself; it fades once it's said it. */
function SavedMark({
  status,
  reduced,
}: {
  status: ActionStatus;
  reduced: boolean;
}) {
  const open = status !== "idle";
  const [label, setLabel] = React.useState("Saving");
  const next =
    status === "pending"
      ? "Saving"
      : status === "success"
        ? "Saved"
        : status === "error"
          ? "Not saved"
          : label;
  if (next !== label) setLabel(next);
  return (
    <span
      aria-hidden="true"
      className={`inline-grid align-baseline text-[11.5px] font-normal ${status === "error" ? "text-red-600 dark:text-red-400" : "text-muted-foreground"}`}
      style={{
        gridTemplateColumns: open ? "1fr" : "0fr",
        opacity: open ? 1 : 0,
        transition: reduced
          ? "none"
          : `grid-template-columns 380ms ${EASE}, opacity ${open ? 240 : 600}ms ${EASE}`,
      }}
    >
      <span className="min-w-0 [clip-path:inset(-4px_0)]">
        <span className="inline-flex items-center gap-1 pl-2 whitespace-nowrap">
          <span className="relative grid size-3 place-items-center">
            <span
              className="absolute inset-0 grid place-items-center"
              style={{
                opacity: status === "pending" ? 1 : 0,
                transition: reduced ? "none" : `opacity 200ms ${EASE}`,
              }}
            >
              <Spinner on={status === "pending"} />
            </span>
            <span
              className="absolute inset-0 grid place-items-center"
              style={{
                opacity: status === "success" ? 1 : 0,
                transition: reduced ? "none" : `opacity 200ms ${EASE}`,
              }}
            >
              <DrawnCheck
                drawn={status === "success"}
                reduced={reduced}
                className="size-3"
              />
            </span>
          </span>
          <TextMorph>{label}</TextMorph>
        </span>
      </span>
    </span>
  );
}

function Label({
  field,
  htmlFor,
  dirty,
  status,
  reduced,
  id,
}: {
  field: SettingsField;
  htmlFor?: string;
  dirty: boolean;
  status: ActionStatus;
  reduced: boolean;
  id: string;
}) {
  const Tag = htmlFor ? "label" : "span";
  return (
    <span className="block min-w-0">
      <Tag
        {...(htmlFor ? { htmlFor } : {})}
        id={`${id}-label`}
        className="flex items-center whitespace-nowrap text-[13px] font-medium tracking-[-0.01em]"
      >
        {field.label}
        {/* A dot that swells in beside a label whose value has changed but isn't saved. */}
        <span
          aria-hidden="true"
          className="ml-1.5 size-1.5 shrink-0 rounded-full bg-primary"
          style={{
            transform: dirty ? "scale(1)" : "scale(0)",
            opacity: dirty ? 1 : 0,
            transition: reduced
              ? "none"
              : `transform 420ms ${dirty ? THROW : EASE}, opacity 200ms ${EASE}`,
          }}
        />
        <SavedMark status={status} reduced={reduced} />
      </Tag>
      {field.description && (
        <span
          id={`${id}-desc`}
          className="mt-0.5 block text-[12px] leading-[1.45] text-muted-foreground"
        >
          {field.description}
        </span>
      )}
    </span>
  );
}

function Switch({
  on,
  onToggle,
  labelledBy,
  describedBy,
  shake,
  reduced,
}: {
  on: boolean;
  onToggle: () => void;
  labelledBy: string;
  describedBy?: string;
  shake: number;
  reduced: boolean;
}) {
  const ref = React.useRef<HTMLButtonElement>(null);
  React.useEffect(() => {
    if (shake && !reduced)
      ref.current?.animate(SHAKE, { duration: 380, easing: "ease-out" });
  }, [shake, reduced]);
  return (
    <button
      ref={ref}
      type="button"
      role="switch"
      aria-checked={on}
      aria-labelledby={labelledBy}
      aria-describedby={describedBy}
      onClick={onToggle}
      className={`relative h-5 w-9 shrink-0 cursor-pointer rounded-full transition-[background-color,box-shadow] duration-300 ${FOCUS} ${on ? "bg-primary" : "bg-muted shadow-[inset_0_0_0_1px_var(--border)]"}`}
    >
      <span
        aria-hidden="true"
        className="absolute top-0.5 left-0.5 size-4 rounded-full bg-background shadow-[0_0_0_1px_var(--border)]"
        style={{
          transform: on ? "translateX(16px)" : "none",
          transition: reduced ? "none" : `transform 420ms ${THROW}`,
        }}
      />
    </button>
  );
}

function Choice({
  field,
  value,
  onChange,
  labelledBy,
  shake,
  reduced,
}: {
  field: Extract<SettingsField, { type: "choice" }>;
  value: string;
  onChange: (v: string) => void;
  labelledBy: string;
  shake: number;
  reduced: boolean;
}) {
  const wrap = React.useRef<HTMLDivElement>(null);
  const refs = React.useRef<(HTMLButtonElement | null)[]>([]);
  const [thumb, setThumb] = React.useState({ left: 0, width: 0, ready: false });
  const index = Math.max(
    0,
    field.options.findIndex((o) => o.value === value),
  );

  React.useLayoutEffect(() => {
    const measure = () => {
      const b = refs.current[index];
      if (!b) return;
      setThumb((t) =>
        t.left === b.offsetLeft && t.width === b.offsetWidth && t.ready
          ? t
          : { left: b.offsetLeft, width: b.offsetWidth, ready: t.width > 0 },
      );
    };
    measure();
    const observer = new ResizeObserver(measure);
    if (wrap.current) observer.observe(wrap.current);
    return () => observer.disconnect();
  }, [index]);

  React.useEffect(() => {
    if (shake && !reduced)
      wrap.current?.animate(SHAKE, { duration: 380, easing: "ease-out" });
  }, [shake, reduced]);

  return (
    <div
      ref={wrap}
      role="radiogroup"
      aria-labelledby={labelledBy}
      className="relative inline-flex shrink-0 rounded-full p-0.5 shadow-[inset_0_0_0_1px_var(--border)]"
    >
      <span
        aria-hidden="true"
        className="absolute top-0.5 bottom-0.5 left-0 rounded-full bg-accent shadow-[inset_0_0_0_1px_var(--border)]"
        style={{
          width: thumb.width,
          transform: `translateX(${thumb.left}px)`,
          transition:
            thumb.ready && !reduced
              ? `transform 460ms ${THROW}, width 360ms ${EASE}`
              : "none",
        }}
      />
      {field.options.map((o, i) => {
        const on = i === index;
        return (
          <button
            key={o.value}
            ref={(el) => {
              refs.current[i] = el;
            }}
            type="button"
            role="radio"
            aria-checked={on}
            tabIndex={on ? 0 : -1}
            onClick={() => onChange(o.value)}
            onKeyDown={(e) => {
              const step =
                e.key === "ArrowRight" || e.key === "ArrowDown"
                  ? 1
                  : e.key === "ArrowLeft" || e.key === "ArrowUp"
                    ? -1
                    : 0;
              if (!step) return;
              e.preventDefault();
              const next =
                (i + step + field.options.length) % field.options.length;
              onChange(field.options[next].value);
              refs.current[next]?.focus();
            }}
            className={`relative h-7 cursor-pointer rounded-full px-3 text-[12px] font-medium transition-colors duration-300 ${FOCUS} ${on ? "text-foreground" : "text-muted-foreground hover:text-foreground"}`}
          >
            {o.label}
          </button>
        );
      })}
    </div>
  );
}

function TextInput({
  field,
  id,
  value,
  error,
  check,
  onChange,
  reduced,
  register,
}: {
  field: TextField;
  id: string;
  value: string;
  error?: string;
  check?: Check;
  onChange: (v: string) => void;
  reduced: boolean;
  register: (
    name: string,
    el: HTMLInputElement | HTMLTextAreaElement | null,
  ) => void;
}) {
  const ring =
    error || check?.state === "no"
      ? "shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--color-red-500)_45%,transparent)]"
      : "shadow-[inset_0_0_0_1px_var(--border)] focus-within:shadow-[inset_0_0_0_1px_var(--ring)]";
  const common = {
    id,
    name: field.name,
    value,
    placeholder: field.placeholder,
    maxLength: field.maxLength,
    "aria-invalid": Boolean(error || check?.state === "no") || undefined,
    "aria-describedby": `${id}-desc ${id}-note`,
    onChange: (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) =>
      onChange(e.target.value),
  };
  const text =
    "bg-transparent text-[16px] text-foreground outline-none placeholder:text-muted-foreground/70 [@media(pointer:fine)]:text-[13.5px]";
  return (
    <div
      data-field-ring=""
      className={`mt-2 rounded-[10px] transition-shadow duration-200 ${ring}`}
    >
      {field.type === "textarea" ? (
        <textarea
          ref={(el) => register(field.name, el)}
          rows={field.rows ?? 3}
          {...common}
          className={`block w-full resize-none px-3 py-2 leading-[1.5] ${text}`}
        />
      ) : (
        <div className="flex h-9 items-center px-3">
          {field.prefix && (
            <span
              aria-hidden="true"
              className="shrink-0 text-[13.5px] text-muted-foreground select-none"
            >
              {field.prefix}
            </span>
          )}
          <input
            ref={(el) => register(field.name, el)}
            type="text"
            inputMode={field.inputMode}
            autoComplete={field.autoComplete ?? "off"}
            {...common}
            className={`h-full min-w-0 flex-1 ${text}`}
          />
          {field.check && (
            <span
              aria-hidden="true"
              className="relative ml-2 grid size-3.5 shrink-0 place-items-center"
            >
              <span
                className="absolute inset-0 grid place-items-center text-muted-foreground"
                style={{
                  opacity: check?.state === "checking" ? 1 : 0,
                  transition: reduced ? "none" : `opacity 200ms ${EASE}`,
                }}
              >
                <Spinner on={check?.state === "checking"} />
              </span>
              <span
                className="absolute inset-0 grid place-items-center text-emerald-600 dark:text-emerald-400"
                style={{
                  opacity: check?.state === "ok" && !error ? 1 : 0,
                  transition: reduced ? "none" : `opacity 200ms ${EASE}`,
                }}
              >
                <DrawnCheck
                  drawn={check?.state === "ok" && !error}
                  reduced={reduced}
                />
              </span>
            </span>
          )}
        </div>
      )}
    </div>
  );
}

export function SettingsForm({
  sections,
  value,
  defaultValue = EMPTY,
  onValueChange,
  onSave,
  autosave = true,
  warnOnLeave = true,
  className = "",
  ...props
}: SettingsFormProps) {
  const reduced = useReducedMotion();
  const id = React.useId();
  const [inner, setInner] = React.useState(defaultValue);
  const saved = value ?? inner;
  const [edits, setEdits] = React.useState<SettingsValues>({});
  const [status, setStatus] = React.useState<Record<string, ActionStatus>>({});
  const [errors, setErrors] = React.useState<Record<string, string>>({});
  const [shakes, setShakes] = React.useState<Record<string, number>>({});
  const [checks, setChecks] = React.useState<Record<string, Check>>({});
  const [bar, setBar] = React.useState<ActionStatus>("idle");
  const [barNote, setBarNote] = React.useState<string | null>(null);
  const [lastCount, setLastCount] = React.useState(1);
  const [announce, setAnnounce] = React.useState("");
  const rootRef = React.useRef<HTMLDivElement>(null);
  const inputs = React.useRef(
    new Map<string, HTMLInputElement | HTMLTextAreaElement>(),
  );
  const runs = React.useRef(new Map<string, number>());
  const checkRuns = React.useRef(
    new Map<string, { timer: number; ctrl?: AbortController }>(),
  );
  const latest = React.useRef({ saved, edits });
  React.useLayoutEffect(() => {
    latest.current = { saved, edits };
  });

  const fields = React.useMemo(
    () => sections.flatMap((s) => s.fields),
    [sections],
  );
  const instant = (f: SettingsField) =>
    autosave && (f.type === "toggle" || f.type === "choice");
  const values = { ...saved, ...edits };
  const dirty = fields.filter(
    (f) =>
      !instant(f) &&
      f.name in edits &&
      edits[f.name] !== (saved[f.name] ?? (f.type === "toggle" ? false : "")),
  );
  const count = dirty.length;
  if (count && count !== lastCount) setLastCount(count);
  const barOpen = count > 0 || bar === "pending" || bar === "success";

  const commitSaved = (next: SettingsValues) => {
    if (value === undefined) setInner(next);
    onValueChange?.(next);
  };

  const register = React.useCallback(
    (name: string, el: HTMLInputElement | HTMLTextAreaElement | null) => {
      if (el) inputs.current.set(name, el);
      else inputs.current.delete(name);
    },
    [],
  );

  // Toggles and choices: saved the moment they change; a newer change wins over an older answer.
  const saveNow = async (f: SettingsField, v: SettingsValue) => {
    const run = (runs.current.get(f.name) ?? 0) + 1;
    runs.current.set(f.name, run);
    setEdits((e) => ({ ...e, [f.name]: v }));
    setStatus((s) => ({ ...s, [f.name]: "pending" }));
    setErrors((e) => without(e, [f.name]));
    try {
      const patch = { [f.name]: v };
      const stored = await onSave(patch, { ...latest.current.saved, ...patch });
      if (runs.current.get(f.name) !== run) return;
      commitSaved({ ...latest.current.saved, ...patch, ...(stored ?? {}) });
      setEdits((e) => without(e, [f.name]));
      setStatus((s) => ({ ...s, [f.name]: "success" }));
      setAnnounce(`${f.label} saved.`);
      window.setTimeout(
        () =>
          setStatus((s) =>
            runs.current.get(f.name) === run && s[f.name] === "success"
              ? { ...s, [f.name]: "idle" }
              : s,
          ),
        1600,
      );
    } catch (e) {
      if (runs.current.get(f.name) !== run) return;
      const why =
        e instanceof SettingsFormError
          ? (e.fields[f.name] ?? e.message)
          : message(e, `${f.label} couldn't be saved.`);
      setEdits((x) => without(x, [f.name]));
      setStatus((s) => ({ ...s, [f.name]: "error" }));
      setErrors((x) => ({ ...x, [f.name]: why }));
      setShakes((x) => ({ ...x, [f.name]: (x[f.name] ?? 0) + 1 }));
      setAnnounce(why);
      window.setTimeout(
        () =>
          setStatus((s) =>
            runs.current.get(f.name) === run && s[f.name] === "error"
              ? { ...s, [f.name]: "idle" }
              : s,
          ),
        2400,
      );
    }
  };

  const edit = (f: TextField, v: string) => {
    setEdits((e) => ({ ...e, [f.name]: v }));
    setErrors((e) => without(e, [f.name]));
    setBarNote(null);
    if (bar === "error" || bar === "success") setBar("idle");
    if (!f.check) return;
    const prev = checkRuns.current.get(f.name);
    if (prev) {
      window.clearTimeout(prev.timer);
      prev.ctrl?.abort();
    }
    if (!v || v === saved[f.name]) {
      setChecks((c) => without(c, [f.name]));
      return;
    }
    const entry: { timer: number; ctrl?: AbortController } = { timer: 0 };
    entry.timer = window.setTimeout(async () => {
      const ctrl = new AbortController();
      entry.ctrl = ctrl;
      setChecks((c) => ({
        ...c,
        [f.name]: { state: "checking", message: "Checking" },
      }));
      try {
        const why = await f.check!(v, { signal: ctrl.signal });
        if (ctrl.signal.aborted) return;
        setChecks((c) => ({
          ...c,
          [f.name]: why
            ? { state: "no", message: why }
            : { state: "ok", message: f.checkPassed ?? "Available" },
        }));
      } catch {
        if (!ctrl.signal.aborted) setChecks((c) => without(c, [f.name]));
      }
    }, 450);
    checkRuns.current.set(f.name, entry);
  };

  const focusFirst = (names: string[]) => {
    const first = fields.find((f) => names.includes(f.name));
    const el = first && inputs.current.get(first.name);
    if (!el) return;
    el.focus({ preventScroll: true });
    el.scrollIntoView({
      block: "nearest",
      behavior: reduced ? "auto" : "smooth",
    });
  };

  const save = async () => {
    if (!count || bar === "pending") return;
    const problems: Record<string, string> = {};
    for (const f of dirty) {
      if (f.type !== "text" && f.type !== "textarea") continue;
      const v = String(values[f.name] ?? "");
      const why =
        f.validate?.(v, values) ||
        (checks[f.name]?.state === "no" ? checks[f.name].message : null);
      if (why) problems[f.name] = why;
    }
    if (Object.keys(problems).length) {
      setErrors((e) => ({ ...e, ...problems }));
      setShakes((s) => ({
        ...s,
        ...Object.fromEntries(
          Object.keys(problems).map((k) => [k, (s[k] ?? 0) + 1]),
        ),
      }));
      setBar("error");
      setBarNote(
        Object.keys(problems).length === 1
          ? "One field needs a look."
          : `${Object.keys(problems).length} fields need a look.`,
      );
      focusFirst(Object.keys(problems));
      return;
    }
    const patch = Object.fromEntries(
      dirty.map((f) => [f.name, values[f.name]]),
    );
    setBar("pending");
    setBarNote(null);
    try {
      const stored = await onSave(patch, { ...latest.current.saved, ...patch });
      commitSaved({ ...latest.current.saved, ...patch, ...(stored ?? {}) });
      // Keep edits made while it was saving.
      setEdits((e) =>
        Object.fromEntries(
          Object.entries(e).filter(([k, v]) => !(k in patch) || v !== patch[k]),
        ),
      );
      setChecks((c) => without(c, Object.keys(patch)));
      setBar("success");
      setAnnounce("Changes saved.");
    } catch (e) {
      const fieldErrors = e instanceof SettingsFormError ? e.fields : {};
      setErrors((x) => ({ ...x, ...fieldErrors }));
      setShakes((s) => ({
        ...s,
        ...Object.fromEntries(
          Object.keys(fieldErrors).map((k) => [k, (s[k] ?? 0) + 1]),
        ),
      }));
      setBar("error");
      const why = message(e, "Your changes couldn't be saved.");
      setBarNote(why);
      setAnnounce(why);
      focusFirst(Object.keys(fieldErrors));
    }
  };

  const reset = () => {
    const names = dirty.map((f) => f.name);
    setEdits((e) => without(e, names));
    setErrors((e) => without(e, names));
    setChecks((c) => without(c, names));
    setBar("idle");
    setBarNote(null);
    if (!reduced)
      for (const n of names)
        inputs.current.get(n)?.animate(
          [
            { opacity: 0.2, filter: "blur(3px)" },
            { opacity: 1, filter: "blur(0px)" },
          ],
          { duration: 420, easing: EASE },
        );
    setAnnounce("Changes discarded.");
  };

  // Saved: the bar says so for a moment, then folds away.
  React.useEffect(() => {
    if (bar !== "success") return;
    const timer = window.setTimeout(() => setBar("idle"), 1100);
    return () => window.clearTimeout(timer);
  }, [bar]);

  React.useEffect(() => {
    if (!warnOnLeave || !count) return;
    const onLeave = (e: BeforeUnloadEvent) => {
      e.preventDefault();
      e.returnValue = "";
    };
    window.addEventListener("beforeunload", onLeave);
    return () => window.removeEventListener("beforeunload", onLeave);
  }, [warnOnLeave, count]);

  React.useEffect(
    () => () =>
      checkRuns.current.forEach(
        (c) => (window.clearTimeout(c.timer), c.ctrl?.abort()),
      ),
    [],
  );

  const shown = count || lastCount;
  const left =
    bar === "success"
      ? "Changes saved"
      : (barNote ?? `${shown} unsaved ${shown === 1 ? "change" : "changes"}`);

  return (
    <div
      ref={rootRef}
      className={`@container relative w-full rounded-[22px] border border-border bg-background text-foreground ${className}`}
      onKeyDown={(e) => {
        if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "s") {
          e.preventDefault();
          save();
        }
      }}
      {...props}
    >
      {sections.map((section, si) => (
        <section
          key={section.title}
          aria-labelledby={`${id}-s${si}`}
          className="grid gap-4 border-t border-border px-4 py-4 first:border-t-0 @xl:grid-cols-[minmax(0,180px)_1fr] @xl:gap-8 @md:px-5 @md:py-5"
        >
          <div className="min-w-0">
            <h3
              id={`${id}-s${si}`}
              className="text-[14px] font-medium tracking-[-0.01em]"
            >
              {section.title}
            </h3>
            {section.description && (
              <p className="mt-0.5 text-[12px] leading-[1.45] text-muted-foreground">
                {section.description}
              </p>
            )}
          </div>
          {/* Its own container: a choice sits beside its label only when this column has room. */}
          <div className="@container/fields min-w-0 space-y-4">
            {section.fields.map((f) => {
              const fid = `${id}-${f.name}`;
              const st = status[f.name] ?? "idle";
              const err = errors[f.name];
              const isDirty = dirty.includes(f);
              const check = checks[f.name];
              const note = err ?? (check ? check.message : null);
              const noteTone =
                err || check?.state === "no"
                  ? "text-red-600 dark:text-red-400"
                  : check?.state === "ok"
                    ? "text-emerald-600 dark:text-emerald-400"
                    : "text-muted-foreground";
              return (
                <div key={f.name}>
                  {f.type === "toggle" ? (
                    <div className="flex items-start justify-between gap-4">
                      <Label
                        field={f}
                        dirty={isDirty}
                        status={st}
                        reduced={reduced}
                        id={fid}
                      />
                      <span className="pt-px">
                        <Switch
                          on={Boolean(values[f.name])}
                          onToggle={() =>
                            instant(f)
                              ? saveNow(f, !values[f.name])
                              : setEdits((e) => ({
                                  ...e,
                                  [f.name]: !values[f.name],
                                }))
                          }
                          labelledBy={`${fid}-label`}
                          describedBy={
                            f.description ? `${fid}-desc` : undefined
                          }
                          shake={shakes[f.name] ?? 0}
                          reduced={reduced}
                        />
                      </span>
                    </div>
                  ) : f.type === "choice" ? (
                    <div className="flex flex-col items-start gap-2 @min-[26rem]/fields:flex-row @min-[26rem]/fields:justify-between @min-[26rem]/fields:gap-4">
                      <Label
                        field={f}
                        dirty={isDirty}
                        status={st}
                        reduced={reduced}
                        id={fid}
                      />
                      <Choice
                        field={f}
                        value={String(
                          values[f.name] ?? f.options[0]?.value ?? "",
                        )}
                        onChange={(v) =>
                          v === values[f.name]
                            ? undefined
                            : instant(f)
                              ? saveNow(f, v)
                              : setEdits((e) => ({ ...e, [f.name]: v }))
                        }
                        labelledBy={`${fid}-label`}
                        shake={shakes[f.name] ?? 0}
                        reduced={reduced}
                      />
                    </div>
                  ) : (
                    <>
                      <Label
                        field={f}
                        htmlFor={fid}
                        dirty={isDirty}
                        status={st}
                        reduced={reduced}
                        id={fid}
                      />
                      <TextInput
                        field={f}
                        id={fid}
                        value={String(values[f.name] ?? "")}
                        error={err}
                        check={check}
                        onChange={(v) => edit(f, v)}
                        reduced={reduced}
                        register={register}
                      />
                      {f.maxLength && f.type === "textarea" && (
                        <p
                          aria-hidden="true"
                          className="mt-1 flex justify-end text-[11px] text-muted-foreground tabular-nums"
                        >
                          <NumberRoll
                            value={String(values[f.name] ?? "").length}
                          />
                          &nbsp;/ {f.maxLength}
                        </p>
                      )}
                    </>
                  )}
                  <div id={`${fid}-note`}>
                    <Fold open={Boolean(note)} reduced={reduced}>
                      <p
                        className={`flex items-center gap-1 pt-1.5 text-[11.5px] ${noteTone}`}
                      >
                        <Line text={note ?? ""} reduced={reduced} />
                      </p>
                    </Fold>
                  </div>
                  {f.type !== "toggle" && f.type !== "choice" && (
                    <ShakeOn
                      getTarget={() => inputs.current.get(f.name)}
                      count={shakes[f.name] ?? 0}
                      reduced={reduced}
                    />
                  )}
                </div>
              );
            })}
          </div>
        </section>
      ))}

      {/* One bar for every unsaved edit; it rises from the foot of the form and stays in view while you scroll. */}
      <div className="sticky bottom-0 z-10">
        <Fold open={barOpen} reduced={reduced}>
          <div
            className="flex items-center gap-3 rounded-b-[21px] border-t border-border bg-background px-4 py-3 @md:px-5"
            role="group"
            aria-label="Unsaved changes"
          >
            <p
              className={`min-w-0 flex-1 text-[12.5px] ${bar === "error" ? "text-red-600 dark:text-red-400" : "text-muted-foreground"}`}
            >
              {bar !== "success" && !barNote ? (
                <span className="flex items-baseline tabular-nums">
                  <NumberRoll value={shown} />
                  &nbsp;
                  <TextMorph>
                    {shown === 1 ? "unsaved change" : "unsaved changes"}
                  </TextMorph>
                </span>
              ) : (
                <Line text={left} reduced={reduced} />
              )}
            </p>
            <button
              type="button"
              onClick={reset}
              disabled={bar === "pending" || !count}
              className={`h-7 cursor-pointer rounded-full px-2.5 text-[12px] font-medium text-muted-foreground transition-colors hover:bg-accent hover:text-foreground disabled:cursor-default disabled:opacity-50 disabled:hover:bg-transparent ${FOCUS}`}
            >
              Reset
            </button>
            <StatusButton
              size="sm"
              status={bar}
              labels={{
                idle: "Save",
                pending: "Saving",
                success: "Saved",
                error: "Try again",
              }}
              onClick={save}
            />
          </div>
        </Fold>
      </div>

      <span className="sr-only" role="status">
        {announce}
      </span>
    </div>
  );
}

/** Shakes an input when its count goes up (a refused value). */
function ShakeOn({
  getTarget,
  count,
  reduced,
}: {
  getTarget: () => HTMLElement | undefined;
  count: number;
  reduced: boolean;
}) {
  React.useEffect(() => {
    if (count && !reduced)
      getTarget()
        ?.closest("[data-field-ring]")
        ?.animate(SHAKE, { duration: 380, easing: "ease-out" });
  }, [count, getTarget, reduced]);
  return null;
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * NUMBER ROLL: numbers that change like an odometer
 *
 *   rolling   each digit is a column that rolls to its new
 *             value, in the direction the number moved: going
 *             up, a 9 rolls on to 0 instead of spinning back
 *   places    new places slide open from nothing; lost ones
 *             fold away
 *   format    anything Intl.NumberFormat does: currency,
 *             percent, compact ("1.2K"), decimals
 *
 * The real number is always there as text for screen readers
 * and copy and paste; the columns are only what you see.
 * ───────────────────────────────────────────────────────── */

export interface NumberRollProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  value: number;
  /** Intl.NumberFormat options, e.g. { style: "currency", currency: "USD" }. */
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
  prefix?: string;
  suffix?: string;
  /** Start from this value and roll to `value` once mounted, e.g. 0 for stats. */
  from?: number;
  /** Roll duration in ms. */
  duration?: number;
  /** Always roll this way, e.g. "down" for a countdown's seconds, which wrap from 00 to 59. Defaults to the way the number moved. */
  direction?: "up" | "down";
}

type Column = { key: string; char: string; digit: number | null };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const SETS = 5; // the strip repeats 0–9 five times so a roll never runs out of digits
const MIDDLE = 20;
/** The strip as one text node, a digit a line: fifty lines, but one element to lay out instead of fifty. */
const STRIP = Array.from({ length: SETS * 10 }, (_, i) => i % 10).join("\n");

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Digits are keyed by their place counted from the right, so the units column stays the units column. */
function columns(text: string): Column[] {
  const chars = [...text];
  const seen = new Map<string, number>();
  let place = 0;
  const out: Column[] = [];
  for (let i = chars.length - 1; i >= 0; i--) {
    const char = chars[i];
    if (/\d/.test(char))
      out.push({ key: `d${place++}`, char, digit: Number(char) });
    else {
      // Symbols are keyed by how many of the same symbol sit to their right, so a comma that shifts is the same comma.
      const n = seen.get(char) ?? 0;
      seen.set(char, n + 1);
      out.push({ key: `s${char}${n}`, char, digit: null });
    }
  }
  return out.reverse();
}

// Memoised: a parent that re-renders with the same number doesn't rebuild the strips.
const Digit = React.memo(function Digit({
  digit,
  trend,
  duration,
  reduced,
  rollIn,
}: {
  digit: number;
  trend: number;
  duration: number;
  reduced: boolean;
  rollIn: boolean;
}) {
  const [pos, setPos] = React.useState(MIDDLE + (rollIn ? 0 : digit));
  const [moving, setMoving] = React.useState(false);
  const posRef = React.useRef(pos);
  const stripRef = React.useRef<HTMLSpanElement>(null);

  React.useLayoutEffect(() => {
    const current = posRef.current;
    const showing = ((current % 10) + 10) % 10;
    if (showing === digit) return;
    if (reduced) {
      posRef.current = MIDDLE + digit;
      setMoving(false);
      setPos(MIDDLE + digit);
      return;
    }
    const up = trend > 0 || (trend === 0 && digit > showing);
    let target = up
      ? current + ((digit - showing + 10) % 10)
      : current - ((showing - digit + 10) % 10);
    // Values arriving faster than a roll (a progress percent) never let it re-centre, so before it runs off the strip,
    // jump the strip back by whole sets mid-roll (it looks identical) and roll on from there.
    if (target < 10 || target > SETS * 10 - 11) {
      const shift = Math.round((target - MIDDLE) / 10) * 10;
      const strip = stripRef.current;
      if (strip?.offsetHeight) {
        let visual = current;
        try {
          visual =
            -new DOMMatrixReadOnly(getComputedStyle(strip).transform).m42 /
            (strip.offsetHeight / (SETS * 10));
        } catch {}
        const transition = strip.style.transition;
        strip.style.transition = "none";
        strip.style.transform = `translateY(${(-(visual - shift) * 100) / (SETS * 10)}%)`;
        void strip.offsetHeight;
        strip.style.transition = transition;
      }
      target -= shift;
    }
    posRef.current = target;
    setMoving(true);
    setPos(target);
  }, [digit, trend, reduced]);

  // After a roll, quietly re-centre on the middle set so the next roll always has room.
  const settle = () => {
    const centred = MIDDLE + (((posRef.current % 10) + 10) % 10);
    posRef.current = centred;
    setMoving(false);
    setPos(centred);
  };

  return (
    <span className="relative inline-block [clip-path:inset(0)]">
      <span className="invisible">{digit}</span>
      <span
        ref={stripRef}
        aria-hidden="true"
        onTransitionEnd={settle}
        className="absolute inset-x-0 top-0 block whitespace-pre text-center"
        style={{
          transform: `translateY(${(-pos * 100) / (SETS * 10)}%)`,
          transition: moving ? `transform ${duration}ms ${EASE}` : "none",
        }}
      >
        {STRIP}
      </span>
    </span>
  );
});

/** A place that appeared after the first paint slides open; places that were there from the start just sit. */
function Place({
  enter,
  children,
}: {
  enter: boolean;
  children: React.ReactNode;
}) {
  const [entering] = React.useState(enter);
  return (
    <span
      className={`inline-block ${entering ? "[clip-path:inset(0)] animate-[ui-col-in_500ms_cubic-bezier(0.16,1,0.3,1)_both]" : ""}`}
    >
      {children}
    </span>
  );
}

export function NumberRoll({
  value,
  format,
  locales,
  prefix = "",
  suffix = "",
  from,
  duration = 900,
  direction,
  className = "",
  ...props
}: NumberRollProps) {
  const reduced = useReducedMotion();
  const [shown, setShown] = React.useState(from ?? value);
  const previous = React.useRef(shown);
  const mounted = React.useRef(false);

  // Roll from `from` to the real value once on screen (a frame later, so the start is painted).
  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setShown(value));
    return () => cancelAnimationFrame(frame);
  }, [value]);

  React.useEffect(() => {
    mounted.current = true;
  }, []);

  const formatter = React.useMemo(
    () => new Intl.NumberFormat(locales, format),
    [locales, format && JSON.stringify(format)],
  );
  const text = `${prefix}${formatter.format(shown)}${suffix}`;
  const cols = React.useMemo(() => columns(text), [text]);
  const trend =
    direction === "up"
      ? 1
      : direction === "down"
        ? -1
        : Math.sign(shown - previous.current);

  // Places that disappear fold away instead of vanishing.
  const [leaving, setLeaving] = React.useState<Column[]>([]);
  const lastCols = React.useRef(cols);
  React.useLayoutEffect(() => {
    const gone = lastCols.current.filter(
      (c) => !cols.some((n) => n.key === c.key),
    );
    lastCols.current = cols;
    previous.current = shown;
    if (!gone.length || reduced) return;
    setLeaving(gone);
    const timer = window.setTimeout(() => setLeaving([]), 420);
    return () => window.clearTimeout(timer);
  }, [cols, shown, reduced]);

  return (
    <span className={`inline-flex tabular-nums ${className}`} {...props}>
      <span className="sr-only">{`${prefix}${formatter.format(value)}${suffix}`}</span>
      <span
        aria-hidden="true"
        className="inline-flex items-baseline whitespace-pre"
      >
        {leaving.map((c) => (
          <span
            key={`out-${c.key}`}
            className="inline-block [clip-path:inset(0)] animate-[ui-col-out_400ms_cubic-bezier(0.16,1,0.3,1)_forwards]"
          >
            {c.char}
          </span>
        ))}
        {cols.map((c) => (
          <Place key={c.key} enter={mounted.current && !reduced}>
            {c.digit === null ? (
              c.char
            ) : (
              <Digit
                digit={c.digit}
                trend={trend}
                duration={duration}
                reduced={reduced}
                rollIn={mounted.current}
              />
            )}
          </Place>
        ))}
      </span>
    </span>
  );
}

"use client";

import * as React from "react";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * STATUS BUTTON: a button that tells you what happened
 *
 *   idle     "Save", with an optional icon
 *   pending  a spinner opens in; the label morphs to "Saving"
 *   success  a check draws itself; "Saved"
 *   error    the button gives a small shake; "Try again"
 *
 * Every change is one motion: the icon slot opens and closes,
 * icons swap through a blur, letters the labels share stay put
 * and the button's width eases to fit.
 * ───────────────────────────────────────────────────────── */

export type ActionStatus = "idle" | "pending" | "success" | "error";

export interface StatusButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  status?: ActionStatus;
  /** Labels per state; defaults to Save, Saving, Saved, Try again. */
  labels?: Partial<Record<ActionStatus, string>>;
  /** Shown before the label while idle. */
  icon?: React.ReactNode;
  variant?: "primary" | "outline" | "ghost";
  /** "sm" is 28px tall, for toolbars and headers. */
  size?: "default" | "sm";
  /** Called this long after success (ms), e.g. to go back to idle. */
  onReset?: () => void;
  resetAfter?: number;
}

const LABELS: Record<ActionStatus, string> = {
  idle: "Save",
  pending: "Saving",
  success: "Saved",
  error: "Try again",
};
const EASE = "cubic-bezier(0.16,1,0.3,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40 focus-visible:ring-offset-2 focus-visible:ring-offset-background";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

function Check({ drawn, reduced }: { drawn: boolean; reduced: boolean }) {
  return (
    <svg viewBox="0 0 16 16" fill="none">
      <path
        d="M3.5 8.5 6.5 11.5 12.5 4.5"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
        pathLength={1}
        strokeDasharray={1}
        style={{
          strokeDashoffset: drawn ? 0 : 1,
          transition:
            drawn && !reduced
              ? `stroke-dashoffset 420ms ${EASE} 120ms`
              : "none",
        }}
      />
    </svg>
  );
}

function Alert() {
  return (
    <svg viewBox="0 0 16 16" fill="none">
      <circle cx="8" cy="8" r="6.25" stroke="currentColor" strokeWidth="1.5" />
      <path
        d="M8 4.75v3.75"
        stroke="currentColor"
        strokeWidth="1.75"
        strokeLinecap="round"
      />
      <circle cx="8" cy="11" r="1" fill="currentColor" />
    </svg>
  );
}

export function StatusButton({
  status = "idle",
  labels,
  icon,
  variant = "primary",
  size = "default",
  onReset,
  resetAfter = 1800,
  className = "",
  onClick,
  ...props
}: StatusButtonProps) {
  const reduced = useReducedMotion();
  const ref = React.useRef<HTMLButtonElement>(null);
  const label = { ...LABELS, ...labels }[status];
  const showIcon = status !== "idle" || Boolean(icon);
  const busy = status === "pending";
  const sm = size === "sm";
  const iconSize = sm ? 14 : 16;

  // A short shake when it fails: the eye catches it even if you looked away.
  React.useEffect(() => {
    if (status !== "error" || reduced) return;
    ref.current?.animate(
      [
        { transform: "none" },
        { transform: "translateX(-4px)" },
        { transform: "translateX(4px)" },
        { transform: "translateX(-2px)" },
        { transform: "none" },
      ],
      { duration: 380, easing: "ease-out" },
    );
  }, [status, reduced]);

  React.useEffect(() => {
    if (status !== "success" || !onReset) return;
    const timer = window.setTimeout(onReset, resetAfter);
    return () => window.clearTimeout(timer);
  }, [status, onReset, resetAfter]);

  const tone =
    status === "error"
      ? "bg-red-500/10 text-red-600 shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--color-red-500)_30%,transparent)] dark:text-red-400"
      : variant === "primary"
        ? "bg-primary text-primary-foreground hover:bg-primary/90"
        : variant === "ghost"
          ? `hover:bg-accent hover:text-foreground ${status === "idle" ? "text-muted-foreground" : "text-foreground"}`
          : "text-foreground shadow-[inset_0_0_0_1px_var(--border)] hover:bg-accent";

  const icons: Record<ActionStatus, React.ReactNode> = {
    idle: icon,
    // Spins only while pending, so a hidden spinner never keeps the page busy.
    pending: (
      <span
        className={`${sm ? "size-3" : "size-3.5"} rounded-full border-[1.5px] border-current border-t-transparent opacity-80 motion-reduce:animate-none ${status === "pending" ? "animate-spin" : ""}`}
      />
    ),
    success: <Check drawn={status === "success"} reduced={reduced} />,
    error: <Alert />,
  };

  return (
    <>
      <button
        ref={ref}
        type="button"
        aria-busy={busy || undefined}
        aria-disabled={busy || undefined}
        onClick={(e) => {
          if (busy) return e.preventDefault();
          onClick?.(e);
        }}
        className={`cursor-pointer disabled:cursor-default aria-disabled:cursor-default inline-flex items-center justify-center whitespace-nowrap rounded-full font-medium transition-[background-color,color,box-shadow,scale,padding] duration-300 active:scale-[0.97] motion-reduce:active:scale-100 ${
          sm
            ? `h-7 text-[12px] ${variant === "ghost" ? "px-2.5" : "px-3"}`
            : "h-9 px-4 text-[13px]"
        } ${FOCUS} ${tone} ${className}`}
        {...props}
      >
        <span
          aria-hidden="true"
          className={`relative flex shrink-0 items-center justify-center ${sm ? "h-3.5 [&_svg]:size-3.5" : "h-4 [&_svg]:size-4"}`}
          style={{
            width: showIcon ? iconSize : 0,
            marginRight: showIcon ? (sm ? 5 : 6) : 0,
            transition: reduced
              ? "none"
              : `width 380ms ${EASE}, margin 380ms ${EASE}`,
          }}
        >
          {(Object.keys(icons) as ActionStatus[]).map((s) => (
            <span
              key={s}
              className="absolute inset-0 flex items-center justify-center"
              style={{
                opacity: s === status ? 1 : 0,
                transform: s === status ? "none" : "scale(0.6)",
                filter: s === status ? "none" : "blur(3px)",
                transition: reduced
                  ? "none"
                  : `opacity 260ms ${EASE}, transform 380ms ${EASE}, filter 260ms ${EASE}`,
              }}
            >
              {icons[s]}
            </span>
          ))}
        </span>
        <TextMorph>{label}</TextMorph>
      </button>
      {/* Outside the button, so the announcement isn't read as part of its name. */}
      <span className="sr-only" role="status">
        {status === "idle" ? "" : label}
      </span>
    </>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * TEXT MORPH: text that changes the way it should
 *
 *   shared   letters both texts share stay alive and slide to
 *            their new place ("Save" → "Saving" keeps "Sav")
 *   new      letters that weren't there rise in out of a blur,
 *            one after another
 *   gone     letters that leave lift away and blur out where
 *            they stood
 *   width    the box eases to its new width, so a button or
 *            pill holding it resizes with it
 *
 * Texts with little in common crossfade as a whole instead of
 * flinging single letters across. The real text is always
 * there for screen readers.
 * ───────────────────────────────────────────────────────── */

export interface TextMorphProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  children: string;
  /** Morph time in ms. */
  duration?: number;
  /** Where new letters come from: below ("up") or above ("down"). */
  direction?: "up" | "down";
  /** Ease the box's width too; turn off for text that wraps. */
  animateWidth?: boolean;
}

type Glyph = { key: number; char: string };
type Leaving = Glyph & { x: number; y: number };

const EASE = "cubic-bezier(0.16,1,0.3,1)";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Keep the letters two texts share (longest common subsequence); everything else is new. */
function morph(
  previous: Glyph[],
  text: string,
  nextKey: () => number,
): Glyph[] {
  const a = previous.map((g) => g.char);
  const b = Array.from(text);
  const fresh = () => b.map((char) => ({ key: nextKey(), char }));
  if (!a.length || !b.length) return fresh();

  const dp = Array.from(
    { length: a.length + 1 },
    () => new Uint16Array(b.length + 1),
  );
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      dp[i][j] =
        a[i] === b[j]
          ? dp[i + 1][j + 1] + 1
          : Math.max(dp[i + 1][j], dp[i][j + 1]);

  // Too little in common reads as two different words: crossfade them instead.
  if (dp[0][0] < Math.min(a.length, b.length) * 0.5) return fresh();

  const out: Glyph[] = [];
  let i = 0;
  let j = 0;
  while (j < b.length) {
    if (i < a.length && a[i] === b[j]) {
      out.push(previous[i++]);
      j++;
    } else if (i < a.length && dp[i + 1][j] >= dp[i][j + 1]) i++;
    else out.push({ key: nextKey(), char: b[j++] });
  }
  return out;
}

function LeavingGlyph({
  glyph,
  lift,
  duration,
  onDone,
}: {
  glyph: Leaving;
  lift: number;
  duration: number;
  onDone: (key: number) => void;
}) {
  const ref = React.useRef<HTMLSpanElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const animation = el.animate(
      [
        { opacity: 1, filter: "blur(0px)", transform: "none" },
        { opacity: 0, filter: "blur(4px)", transform: `translateY(${lift}em)` },
      ],
      { duration: duration * 0.6, easing: EASE, fill: "forwards" },
    );
    animation.onfinish = () => onDone(glyph.key);
    return () => animation.cancel();
  }, [glyph.key, lift, duration, onDone]);
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className="pointer-events-none absolute whitespace-pre"
      style={{ left: glyph.x, top: glyph.y }}
    >
      {glyph.char}
    </span>
  );
}

export function TextMorph({
  children: text,
  duration = 460,
  direction = "up",
  animateWidth = true,
  className = "",
  ...props
}: TextMorphProps) {
  const reduced = useReducedMotion();
  const counter = React.useRef(text.length);
  const nextKey = React.useCallback(() => ++counter.current, []);
  const [glyphs, setGlyphs] = React.useState<Glyph[]>(() =>
    Array.from(text).map((char, i) => ({ key: i + 1, char })),
  );
  const [leaving, setLeaving] = React.useState<Leaving[]>([]);
  const rootRef = React.useRef<HTMLSpanElement>(null);
  const els = React.useRef(new Map<number, HTMLSpanElement>());
  const before = React.useRef<{
    at: Map<number, { x: number; y: number }>;
    width: number;
  } | null>(null);
  const rise = direction === "up" ? 0.35 : -0.35;

  // A preference change must also finish an in-flight morph whose target text
  // already matches the glyphs (including the empty label in a folded receipt).
  React.useLayoutEffect(() => {
    if (!reduced) return;
    before.current = null;
    const root = rootRef.current;
    root
      ?.getAnimations({ subtree: true })
      .forEach((animation) => animation.cancel());
    if (root) root.style.whiteSpace = "";
    setLeaving((previous) => (previous.length ? [] : previous));
  }, [reduced]);

  // 1. The text changed: note where every letter stands, then work out which letters stay.
  React.useLayoutEffect(() => {
    if (text === glyphs.map((g) => g.char).join("")) return;
    const root = rootRef.current;
    if (!root || reduced) {
      setLeaving([]);
      setGlyphs(Array.from(text).map((char) => ({ key: nextKey(), char })));
      return;
    }
    const box = root.getBoundingClientRect();
    const at = new Map<number, { x: number; y: number }>();
    els.current.forEach((el, key) => {
      const r = el.getBoundingClientRect();
      at.set(key, { x: r.left - box.left, y: r.top - box.top });
    });
    before.current = { at, width: box.width };
    const next = morph(glyphs, text, nextKey);
    const kept = new Set(next.map((g) => g.key));
    setLeaving((l) => [
      ...l,
      ...glyphs
        .filter((g) => !kept.has(g.key))
        .map((g) => ({ ...g, ...(at.get(g.key) ?? { x: 0, y: 0 }) })),
    ]);
    setGlyphs(next);
  }, [text, reduced]);

  // 2. The new letters are in place: glide the ones that stayed, raise the new ones, ease the width.
  React.useLayoutEffect(() => {
    const prev = before.current;
    const root = rootRef.current;
    if (!prev || !root) return;
    before.current = null;
    const box = root.getBoundingClientRect();
    let order = 0;
    for (const g of glyphs) {
      const el = els.current.get(g.key);
      if (!el) continue;
      const from = prev.at.get(g.key);
      if (from) {
        const r = el.getBoundingClientRect();
        const dx = from.x - (r.left - box.left);
        const dy = from.y - (r.top - box.top);
        if (Math.abs(dx) > 0.5 || Math.abs(dy) > 0.5)
          el.animate(
            [
              { transform: `translate(${dx}px, ${dy}px)` },
              { transform: "none" },
            ],
            { duration, easing: EASE },
          );
      } else {
        el.animate(
          [
            {
              opacity: 0,
              filter: "blur(4px)",
              transform: `translateY(${rise}em)`,
            },
            { opacity: 1, filter: "blur(0px)", transform: "none" },
          ],
          {
            duration,
            easing: EASE,
            delay: Math.min(order++ * 16, 160),
            fill: "backwards",
          },
        );
      }
    }
    if (animateWidth && Math.abs(prev.width - box.width) > 0.5) {
      // Hold the words on one line while the box is narrower than them, or "No credits left" would wrap mid-morph.
      root.style.whiteSpace = "nowrap";
      const resize = root.animate(
        [{ width: `${prev.width}px` }, { width: `${box.width}px` }],
        { duration, easing: EASE },
      );
      resize.onfinish = resize.oncancel = () => {
        root.style.whiteSpace = "";
      };
    }
  }, [glyphs, duration, rise, animateWidth]);

  const done = React.useCallback(
    (key: number) => setLeaving((l) => l.filter((g) => g.key !== key)),
    [],
  );

  // Words stay unbroken; lines may only wrap at spaces.
  const words: Glyph[][] = [];
  for (const g of glyphs) {
    if (
      g.char === " " ||
      !words.length ||
      words[words.length - 1][0]?.char === " "
    )
      words.push([g]);
    else words[words.length - 1].push(g);
  }

  return (
    <span
      ref={rootRef}
      className={`relative inline-block ${className}`}
      {...props}
    >
      <span className="sr-only">{text}</span>
      {words.map((word, w) => (
        <span
          key={w}
          aria-hidden="true"
          className="inline-block whitespace-pre"
        >
          {word.map((g) => (
            <span
              key={g.key}
              ref={(el) => {
                if (el) els.current.set(g.key, el);
                else els.current.delete(g.key);
              }}
              className="inline-block"
            >
              {g.char}
            </span>
          ))}
        </span>
      ))}
      {leaving.map((g) => (
        <LeavingGlyph
          key={`out-${g.key}`}
          glyph={g}
          lift={-rise}
          duration={duration}
          onDone={done}
        />
      ))}
    </span>
  );
}

